//! Typst renderer and on-disk bundle writer.
//!
//! The renderer turns the backend-neutral document into a small, readable
//! Typst source file. Diagram assets are written next to the source in a
//! dedicated folder, so the generated file is self-contained apart from the
//! local Typst compiler.

use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;

use anyhow::{Context, Result, bail};

use super::{Diagram, PrintDocument, PrintItem};

/// Files written by [`write_bundle`].
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct PrintBundle {
    pub source: PathBuf,
    pub diagrams: Vec<PathBuf>,
}

/// Render a document as Typst source that references `diagrams/…` assets.
pub fn source(document: &PrintDocument) -> String {
    source_with_diagram_dir(document, "diagrams")
}

/// Write the Typst source and its SVG diagrams next to `path`.
///
/// The diagram folder is named `<stem>_diagrams`. Only old `diagram-*.svg`
/// files in that folder are removed, so unrelated files are left untouched.
pub fn write_bundle(path: &Path, document: &PrintDocument) -> Result<PrintBundle> {
    let parent = path
        .parent()
        .filter(|parent| !parent.as_os_str().is_empty())
        .unwrap_or_else(|| Path::new("."));
    let stem = path
        .file_stem()
        .and_then(|stem| stem.to_str())
        .filter(|stem| !stem.is_empty())
        .unwrap_or("print");
    let folder_name = format!("{stem}_diagrams");
    let folder = parent.join(&folder_name);

    fs::create_dir_all(&folder)
        .with_context(|| format!("creating diagram folder {}", folder.display()))?;
    for entry in fs::read_dir(&folder).with_context(|| format!("reading {}", folder.display()))? {
        let entry = entry.with_context(|| format!("reading {}", folder.display()))?;
        let name = entry.file_name();
        let name = name.to_string_lossy();
        if name.starts_with("diagram-") && name.ends_with(".svg") {
            fs::remove_file(entry.path())
                .with_context(|| format!("removing stale diagram {}", entry.path().display()))?;
        }
    }

    let mut diagrams = Vec::with_capacity(document.diagrams.len());
    for (index, diagram) in document.diagrams.iter().enumerate() {
        let file_name = format!("diagram-{:02}.svg", index + 1);
        let diagram_path = folder.join(&file_name);
        fs::write(&diagram_path, &diagram.svg)
            .with_context(|| format!("writing diagram {}", diagram_path.display()))?;
        diagrams.push(diagram_path);
    }

    let folder_name = folder
        .file_name()
        .map(|name| name.to_string_lossy().into_owned())
        .unwrap_or_else(|| "diagrams".to_string());
    let source = source_with_diagram_dir(document, &folder_name);
    fs::write(path, source).with_context(|| format!("writing {}", path.display()))?;

    Ok(PrintBundle {
        source: path.to_path_buf(),
        diagrams,
    })
}

/// Compile a generated `.typ` file to PDF with `BRETT_TYPST` or `typst`.
pub fn compile_pdf(typst_path: &Path, pdf_path: &Path) -> Result<()> {
    let compiler = std::env::var_os("BRETT_TYPST")
        .filter(|value| !value.is_empty())
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from("typst"));
    let output = Command::new(&compiler)
        .arg("compile")
        .arg(typst_path)
        .arg(pdf_path)
        .output()
        .with_context(|| {
            format!(
                "could not run {}; install Typst or set BRETT_TYPST",
                compiler.display()
            )
        })?;
    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr);
        let stderr = stderr.trim();
        if stderr.is_empty() {
            bail!("Typst compilation failed with status {}", output.status);
        }
        bail!("Typst compilation failed: {stderr}");
    }
    Ok(())
}

fn source_with_diagram_dir(document: &PrintDocument, diagram_dir: &str) -> String {
    let mut out = String::with_capacity(8 * 1024);
    out.push_str("// Generated by Brett. Do not edit by hand.\n");
    out.push_str("#set page(\n");
    out.push_str("  paper: \"a4\",\n");
    out.push_str("  margin: (x: 1.55cm, top: 2.1cm, bottom: 1.5cm),\n");
    out.push_str("  columns: 2,\n");
    out.push_str("  header: context {\n");
    out.push_str("    set text(size: 7.5pt, fill: luma(80))\n");
    out.push_str("    grid(\n");
    out.push_str("      columns: (1fr, auto),\n");
    out.push_str(&format!(
        "      [#text({})],\n",
        typst_string(&header_line(document))
    ));
    out.push_str("      counter(page).display(),\n");
    out.push_str("    )\n");
    out.push_str("    v(-0.2em)\n");
    out.push_str("    line(length: 100%, stroke: 0.4pt + luma(160))\n");
    out.push_str("  },\n");
    out.push_str(")\n");
    out.push_str("#set text(font: (\"DejaVu Serif\", \"Liberation Serif\"), size: 9.5pt)\n");
    out.push_str("#set par(justify: true, leading: 0.55em, spacing: 0.35em)\n\n");

    write_heading(document, &mut out);

    let mut used = std::collections::BTreeSet::new();
    write_items(
        &document.game.items,
        0,
        diagram_dir,
        &document.diagrams,
        &mut used,
        &mut out,
    );

    // The empty-game case has no move item to attach its start diagram to.
    for (index, diagram) in document.diagrams.iter().enumerate() {
        if used.insert(index) {
            write_diagram(diagram, index, 0, diagram_dir, &mut out);
        }
    }

    out.push_str(&format!(
        "\n#block(above: 0.4em)[#text(weight: \"bold\", {})]\n",
        typst_string(&document.game.result)
    ));
    if !document.diagrams.is_empty() {
        out.push_str("#block(above: 0.6em)[#text(size: 7pt, fill: luma(110), \"Board pieces: cburnett by Colin M. L. Burnett, CC BY-SA 3.0.\")]\n");
    }
    out
}

fn write_heading(document: &PrintDocument, out: &mut String) {
    let white = header(document, "White").unwrap_or("?");
    let black = header(document, "Black").unwrap_or("?");
    let white_elo = header(document, "WhiteElo").filter(|elo| !elo.trim().is_empty());
    let black_elo = header(document, "BlackElo").filter(|elo| !elo.trim().is_empty());
    let eco = header(document, "ECO")
        .filter(|code| !code.trim().is_empty())
        .map(|code| format!("ECO {code}"))
        .unwrap_or_default();
    let event_line = ["Event", "Site", "Round"]
        .iter()
        .filter_map(|key| header(document, key))
        .filter(|value| !value.trim().is_empty())
        .collect::<Vec<_>>()
        .join(" · ");
    let date = header(document, "Date")
        .filter(|date| !date.trim().is_empty())
        .unwrap_or("");

    out.push_str("#block(breakable: false, width: 100%)[\n");
    out.push_str("  #set par(justify: false)\n");
    out.push_str("  #grid(\n");
    out.push_str("    columns: (1fr, auto),\n");
    out.push_str("    column-gutter: 1em,\n");
    out.push_str("    align: (left, right),\n");
    out.push_str("    [\n");
    out.push_str("      #grid(\n");
    out.push_str("        columns: (1fr, auto),\n");
    out.push_str("        column-gutter: 0.6em,\n");
    out.push_str("        row-gutter: 0.12em,\n");
    out.push_str("        align: (left, right),\n");
    write_player_row(out, "white", white, white_elo);
    write_player_row(out, "black", black, black_elo);
    out.push_str("      )\n");
    out.push_str("    ],\n");
    out.push_str(&format!(
        "    [#text(size: 10pt, weight: \"bold\", fill: luma(60), {})],\n",
        typst_string(&eco)
    ));
    out.push_str("  )\n");

    if !event_line.is_empty() || !date.is_empty() {
        out.push_str("  #grid(\n");
        out.push_str("    columns: (1fr, auto),\n");
        out.push_str("    column-gutter: 1em,\n");
        out.push_str("    align: (left, right),\n");
        out.push_str(&format!(
            "    [#text(size: 8.5pt, fill: luma(70), {})],\n",
            typst_string(&event_line)
        ));
        out.push_str(&format!(
            "    [#text(size: 8.5pt, fill: luma(70), {})],\n",
            typst_string(date)
        ));
        out.push_str("  )\n");
    }

    let mut lines = Vec::new();
    if let Some(fen) = &document.game.start_fen {
        lines.push(format!("Start position: {fen}"));
    }
    if let Some(variant) = &document.game.variant {
        lines.push(format!("Variant: {variant}"));
    }
    for line in &lines {
        out.push_str(&format!(
            "  #text(size: 8.5pt, fill: luma(70), {})\n",
            typst_string(line)
        ));
    }
    out.push_str("]\n#v(0.4em)\n\n");
}

fn write_player_row(out: &mut String, color: &str, name: &str, elo: Option<&str>) {
    let (fill, stroke) = if color == "white" {
        ("white", ", stroke: 0.6pt + luma(60)")
    } else {
        ("black", "")
    };
    out.push_str(&format!(
        "        [#box(width: 0.7em, height: 0.7em, fill: {fill}{stroke}) #text(size: 11pt, weight: \"bold\", {})], [#text(size: 8.5pt, fill: luma(70), {})],\n",
        typst_string(name),
        typst_string(elo.unwrap_or(""))
    ));
}

fn write_items(
    items: &[PrintItem],
    depth: usize,
    diagram_dir: &str,
    diagrams: &[Diagram],
    used: &mut std::collections::BTreeSet<usize>,
    out: &mut String,
) {
    for item in items {
        match item {
            PrintItem::Move(mv) => {
                if mv.bold {
                    out.push_str(&format!(
                        "#text(weight: \"bold\", {}) ",
                        typst_string(&mv.text)
                    ));
                } else {
                    out.push_str(&format!("#text({}) ", typst_string(&mv.text)));
                }
            }
            PrintItem::Comment(text) => {
                out.push_str(&format!(
                    "#block(inset: (left: {:.1}em), above: 0.15em, below: 0.15em)[#text({})]\n",
                    indent(depth),
                    typst_string(text)
                ));
            }
            PrintItem::Annotation(text) => {
                out.push_str(&format!(
                    "#block(inset: (left: {:.1}em), above: 0.05em, below: 0.15em)[#text(size: 8pt, fill: luma(90), {})]\n",
                    indent(depth),
                    typst_string(text)
                ));
            }
            PrintItem::Variation(items) => {
                out.push_str(&format!(
                    "#block(inset: (left: {:.1}em), above: 0.15em, below: 0.15em)[#text(\"[\") ",
                    indent(depth)
                ));
                write_items(items, depth + 1, diagram_dir, diagrams, used, out);
                out.push_str("#text(\"]\")]\n");
            }
            PrintItem::Diagram(index) => {
                if let Some(diagram) = diagrams.get(*index) {
                    used.insert(*index);
                    write_diagram(diagram, *index, depth, diagram_dir, out);
                }
            }
        }
    }
}

fn write_diagram(
    diagram: &Diagram,
    index: usize,
    depth: usize,
    diagram_dir: &str,
    out: &mut String,
) {
    ensure_paragraph_break(out);
    let path = format!("{diagram_dir}/diagram-{:02}.svg", index + 1);
    out.push_str(&format!(
        "#block(breakable: false, inset: (left: {:.1}em), above: 0.4em, below: 0.4em)[#image({}, width: 86%) #linebreak() #text(size: 8pt, style: \"italic\", {})]\n",
        indent(depth),
        typst_string(&path),
        typst_string(&diagram.caption)
    ));
    out.push('\n');
}

/// Start the diagram on a fresh paragraph so the moves before it are laid out
/// as a complete unit and the moves after it continue after the board.
fn ensure_paragraph_break(out: &mut String) {
    if out.is_empty() {
        return;
    }
    if !out.ends_with('\n') {
        out.push('\n');
    }
    if !out.ends_with("\n\n") {
        out.push('\n');
    }
}

fn indent(depth: usize) -> f64 {
    (depth + 1) as f64 * 1.2
}

fn header_line(document: &PrintDocument) -> String {
    format!(
        "Brett print · {} · {} · {}",
        document.meta.source, document.meta.owner, document.meta.date
    )
}

fn header<'a>(document: &'a PrintDocument, key: &str) -> Option<&'a str> {
    document
        .game
        .headers
        .iter()
        .find(|(name, _)| name.eq_ignore_ascii_case(key))
        .map(|(_, value)| value.as_str())
}

/// Quote a string for Typst, escaping backslashes, quotes, and control
/// characters. Text inside a Typst string is never interpreted as markup.
fn typst_string(text: &str) -> String {
    let mut out = String::with_capacity(text.len() + 2);
    out.push('"');
    for ch in text.chars() {
        match ch {
            '\\' => out.push_str("\\\\"),
            '"' => out.push_str("\\\""),
            '\n' => out.push_str("\\n"),
            '\r' => {}
            '\t' => out.push_str("\\t"),
            _ => out.push(ch),
        }
    }
    out.push('"');
    out
}
